/**
 * Dungeons (CR 309) and venturing into the dungeon (CR 701.49). Owner: MX4.
 *
 * The dungeon cards are data: core/dungeons.json (generated by scripts/gen-dungeons.ts from their Oracle text; each room ability compiled by the game's own
 * compiler, a room the compiler can't read is a manual ability). A dungeon in the game is a `card` object in its owner's command zone (CR 309.2b) with the
 * synthetic definition `dungeon:<name>` (its rooms are its abilities, in room order) and the venture marker as `GameObject.ventureRoom` (CR 309.4).
 *
 *  - `ventureIntoDungeon` (CR 701.49a-d, 309.5): bring a dungeon in (the player chooses one they own from outside the game: every player owns the dungeon
 *    cards, as in every real game; "venture into Undercity" offers Undercity only, and Undercity is offered only then: "You can't enter this dungeon unless
 *    you venture into Undercity."), or move the marker to the next room (the player chooses the arrow, CR 309.5a), or, on the bottommost room, complete the
 *    dungeon (CR 701.49c) and bring in a new one. Moving the marker into a room triggers that room's ability (CR 309.4c: "When you move your venture marker
 *    into this room, [effect]"), controlled by the dungeon's owner.
 *  - `dungeonSbas` (CR 704.5t, 309.6): a dungeon whose marker is on its bottommost room and which isn't the source of a room ability that has triggered but
 *    not yet left the stack is removed from the game: its owner completes it (CR 309.7).
 *  - Completing a dungeon records its name in `GameState.designations.completedDungeons` (the `completedDungeon` condition) and emits the action
 *    `completeDungeon` ("whenever you complete a dungeon").
 */
import type { AbilityDef } from '../types/ability';
import type { CardDef } from '../types/card';
import type { ObjectId, PlayerId } from '../types/ids';
import type { GameObject, GameState, PendingTrigger } from '../types/state';
import type { AutomationLevel } from '../types/automation';
import { DEF_PREFIX, DUNGEONS, UNDERCITY, dungeonByName, dungeonInCommand, dungeonOfObject, type Dungeon } from './dungeon-data';
import type { Game } from './game';
import { freshObject } from './zones';

export * from './dungeon-data';

/** The level of a dungeon card: `full` when every room ability is, `manual` when none runs, `partial` otherwise (design 10: computed, never asserted). */
function dungeonLevel(d: Dungeon): AutomationLevel {
  if (d.rooms.every((r) => r.level === 'full')) return 'full';
  return d.rooms.every((r) => r.level === 'manual') ? 'manual' : 'partial';
}

/** The definition of a dungeon card: one face, type Dungeon, its rooms' abilities in room order (CR 309.4c), functioning in the command zone. */
export function dungeonDef(d: Dungeon): CardDef {
  const abilities = d.rooms.map((r) => ({ ...r.ability, zone: ['command'] }) as AbilityDef);
  const text = [...(d.note ? [d.note] : []), ...d.rooms.map((r) => `${r.name} — ${r.text}${r.next.length > 0 ? ` (Leads to: ${r.next.map((i) => d.rooms[i]!.name).join(', ')})` : ''}`)].join('\n');
  return {
    id: `${DEF_PREFIX}${d.name}`,
    name: d.name,
    layout: 'normal',
    isToken: false,
    faces: [{
      name: d.name, manaCost: null, typeLine: d.subtypes.length > 0 ? `Dungeon — ${d.subtypes.join(' ')}` : 'Dungeon', supertypes: [], types: ['Dungeon'],
      subtypes: [...d.subtypes], colors: [], keywords: [], oracleText: text, abilities,
    }],
    automation: { level: dungeonLevel(d), unsupported: d.rooms.filter((r) => r.level !== 'full').map((r) => `${r.name} — ${r.text}`), source: 'templates' },
  };
}

/** CR 309.4c: moving the venture marker into a room triggers its room ability, controlled by the dungeon's owner. */
function triggerRoom(g: Game, o: GameObject, d: Dungeon, room: number): void {
  const r = d.rooms[room]!;
  const t: PendingTrigger = {
    id: `t${g.s.counters.effect++}`,
    sourceId: o.id,
    sourceName: d.name,
    controller: o.owner,
    abilityRef: { source: 'printed', face: 0, index: room },
    context: { ev: 'state', roles: {}, before: {} },
    inline: { ...r.ability, zone: ['command'] } as AbilityDef,
  };
  g.s.pendingTriggers.push(t);
  g.log(`${g.player(o.owner).name}'s venture marker moves into ${r.name} (${d.name}): ${r.text}`, { rules: ['CR 309.4c', 'CR 701.49'], level: 'action' });
}

/** CR 309.2a, 701.49a, 701.49d: the player chooses a dungeon card they own from outside the game and puts it into the command zone, marker on the top room. */
function enterDungeon(g: Game, player: PlayerId, quality: string | undefined): void {
  const options = DUNGEONS.filter((d) => (quality === undefined ? !d.subtypes.includes(UNDERCITY) : d.subtypes.includes(quality) || d.name === quality));
  if (options.length === 0) {
    g.log(`${g.player(player).name} has no dungeon to venture into.`, { rules: ['CR 701.49a'], level: 'info' });
    return;
  }
  const name = options.length === 1 ? options[0]!.name : g.choose({
    kind: 'chooseOption', player, prompt: 'Venture into the dungeon: choose a dungeon to enter.', min: 1, max: 1, rules: ['CR 701.49a', 'CR 309.2a'],
    options: options.map((d) => ({ id: d.name, label: `${d.name} (${d.rooms.length} rooms; first: ${d.rooms[0]!.name} — ${d.rooms[0]!.text})` })),
  }).ids[0]!;
  const d = dungeonByName(name)!;
  const def = dungeonDef(d);
  g.addDef(def);
  const o = freshObject(g, { kind: 'card', defId: def.id, owner: player, controller: player }, 'command');
  o.ventureRoom = 0; // CR 309.4a
  g.s.objects[o.id] = o;
  g.s.zones.command.push(o.id);
  g.log(`${g.player(player).name} enters ${d.name}.`, { rules: ['CR 309.2a', 'CR 309.4a'], level: 'action' });
  triggerRoom(g, o, d, 0);
}

/** CR 309.7: the owner removes the dungeon from the game and so completes it; recorded, and "whenever you complete a dungeon" sees it. */
function completeDungeon(g: Game, o: GameObject, d: Dungeon, rules: string[]): void {
  const i = g.s.zones.command.indexOf(o.id);
  if (i >= 0) g.s.zones.command.splice(i, 1);
  g.s.lki[o.id] = { object: { ...o }, chars: null, leftZone: 'command' };
  delete g.s.objects[o.id];
  const done = { ...(g.s.designations.completedDungeons ?? {}) };
  done[o.owner] = [...(done[o.owner] ?? []), d.name];
  g.s.designations.completedDungeons = done;
  g.log(`${g.player(o.owner).name} completes ${d.name}.`, { rules: [...rules, 'CR 309.7'], level: 'action' });
  g.emit({ type: 'actionPerformed', verb: 'completeDungeon', actor: o.owner });
}

/**
 * CR 701.49: the player ventures into the dungeon (`quality`: "venture into Undercity", CR 701.49d). Returns whether the venture marker moved (it does not
 * when the player has lost or no dungeon can be entered).
 */
export function ventureIntoDungeon(g: Game, player: PlayerId, quality?: string): boolean {
  if (g.player(player).hasLost) return false;
  g.emit({ type: 'actionPerformed', verb: 'venture', actor: player });
  const o = dungeonInCommand(g.s, player);
  const d = dungeonOfObject(o);
  if (!o || !d) {
    enterDungeon(g, player, quality);
    return true;
  }
  const room = o.ventureRoom ?? 0;
  const next = d.rooms[room]?.next ?? [];
  if (next.length === 0) {
    // CR 701.49c: on the bottommost room, the dungeon is completed and a new one entered ("an appropriate dungeon": one with the quality, CR 701.49d)
    completeDungeon(g, o, d, ['CR 701.49c']);
    enterDungeon(g, player, quality);
    return true;
  }
  // CR 701.49b, 309.5a: the player chooses an arrow when there are several
  const to = next.length === 1 ? next[0]! : Number(g.choose({
    kind: 'chooseOption', player, prompt: `Venture into the dungeon (${d.name}): choose the next room.`, min: 1, max: 1, rules: ['CR 701.49b', 'CR 309.5a'],
    options: next.map((i) => ({ id: String(i), label: `${d.rooms[i]!.name} — ${d.rooms[i]!.text}` })),
  }).ids[0]);
  o.ventureRoom = to;
  triggerRoom(g, o, d, to);
  return true;
}

/** True while the object is the source of an ability that has triggered but not yet left the stack (CR 704.5t). */
function sourceOfPendingAbility(s: GameState, id: ObjectId): boolean {
  return s.pendingTriggers.some((t) => t.sourceId === id) || s.zones.stack.some((sid) => s.objects[sid]?.stack?.kind === 'triggered' && s.objects[sid]?.stack?.sourceId === id);
}

/** CR 704.5t, 309.6: completed dungeons leave the game. Returns whether any did. */
export function dungeonSbas(g: Game): boolean {
  const done: { o: GameObject; d: Dungeon }[] = [];
  for (const id of g.s.zones.command) {
    const o = g.s.objects[id];
    const d = dungeonOfObject(o);
    if (!o || !d) continue;
    if ((d.rooms[o.ventureRoom ?? 0]?.next.length ?? 1) > 0) continue;
    if (sourceOfPendingAbility(g.s, o.id)) continue;
    done.push({ o, d });
  }
  for (const { o, d } of done) completeDungeon(g, o, d, ['CR 704.5t', 'CR 309.6']);
  return done.length > 0;
}
